// disconnect the connection
void connectionTCP::disconnectTCP(bool isMain)
{
		// A finished custom battle has already left the tactical world, so
		// coopBattleLive() is false while its DebriefingState is still open.
		// Remember that exact state before teardown resets the session: a client
		// leaving at the results screen must not send the host back to the lobby.
		bool customBattleDebriefing = false;
		if (_game && _game->getSavedGame()
			&& _game->getSavedGame()->getMonthsPassed() == -1)
		{
			for (State* st : _game->getStates())
			{
				if (dynamic_cast<DebriefingState*>(st) != nullptr)
				{
					customBattleDebriefing = true;
					break;
				}
			}
		}

		_waitBC = false;
		_waitBH = false;
		coopSession = false;
		// coop: clear the cached teammate geoscape speed/focus so a stale '+' marker
		// doesn't linger after disconnect.
		peerTimeSpeedId = "";
		peerFocusScreen = -1;
		connectionTCP::lobby_timer = -1;
		connectionTCP::isPlayerReady = false;
		connectionTCP::isPlayersReady = false;

		connectionTCP::LobbyFileStatus = -1;
		// issue #93: a drop mid-mission is a freeze, not the end of the session -
		// the peer is expected back in the SAME battle, and the game mode
		// (PVE/PVP/PVE2) decides which units each machine commands. Zeroing it
		// here would hand a rejoining player the wrong side of its own battle.
		if (!coopBattleLive(_game))
		{
			connectionTCP::_coopGamemode = 0;
		}
		connectionTCP::show_inactive_player_inventory = false;
		// A transport drop can happen while VoteMenu is the top state. Mark it as
		// cancelled before clearing the controller state so the popup always gains
		// a CLOSE button instead of waiting forever for vote_result.
		if (_activeVote.id != 0)
		{
			VoteMenu* voteMenu = findVoteMenu(_activeVote.id);
			if (voteMenu)
			{
				voteMenu->cancelVote();
			}
		}
		_activeVote.clear();
		_voteRequestPending = false;
		_voteStarterCooldownUntil.clear();

		// Capture the machine role ONCE for this teardown - handlers used to
		// mutate server_owner mid-flight and make the cleanup misclassify the
		// machine (the disconnect->cancel bug family). Hoisted ABOVE
		// clearNetworkSessionQueues() below (SPEC 16 M1): the mid-Active-battle
		// spare gate needs it before that call runs, not after.
		const bool teardownAsHost = (session.role == CoopRole::Host);

		// SPEC 16 (W1-P17) M1 (F331 gate; owner-ruled mechanism, DECIDED (b)):
		// a mid-`Active`-battle peer leave keeps the co-op battle authority
		// ALIVE instead of tearing it down to Idle - the host survives, a
		// client left, and a battle is actually live and Active right now.
		// This is the ONLY site that ever passes resetAuthority=false to
		// clearNetworkSessionQueues(); every other teardown (lobby, a
		// handshake-phase leave, a full close, a leave once the campaign has
		// ended) keeps the unconditional F331 reset unchanged.
		const bool spareAuthorityOnPeerAbsent =
			teardownAsHost
			&& onConnect == -2
			&& coopBattleLive(_game)
			&& !campaignEnded()
			&& coopBattleAuthority().phase == CoopBattlePhase::Active;

		// SPEC 16 (W1-P17) M4: a DELIBERATE client leave (isMain - the
		// caller is already committed to the teardown, e.g.
		// disconnect_to_menu/ABANDON/SAVE&QUIT, as opposed to a passive
		// disconnect this function discovers on its own) tells the host
		// BEFORE the transport goes down, so the pause dialog can name the
		// reason. Sent here, before clearNetworkSessionQueues() a few lines
		// below would otherwise erase this very message from g_txQ out from
		// under the socket thread's own drain of it (F341: this buys no
		// latency - liveness detection alone already raises the pause
		// dialog in ~0.1s for a graceful quit or a kill() alike; its only
		// value is the label).
		if (isMain && !teardownAsHost && coopBattleLive(_game)
			&& coopBattleAuthority().phase == CoopBattlePhase::Active)
		{
			Json::Value leave = CoopWire::makeLeave(coopBattleAuthority().localSeat, "quit");
			CoopEmit::sendBattle(leave);
			// Best-effort bounded drain: give the socket sender thread (the
			// SPSC consumer of g_txQ) a window to pop this message before it
			// races clearNetworkSessionQueues()'s own drain-and-discard loop
			// below. Same bounded-wait shape as coopEmitBlockingPush()'s
			// MN-8 bypass; capped at 100ms so a dead transport (onConnect<0,
			// nothing will ever drain g_txQ again) cannot stall a
			// deliberate quit.
			for (int i = 0; i < 50 && !g_txQ.empty() && onConnect >= 0; ++i)
			{
				std::this_thread::sleep_for(std::chrono::milliseconds(2));
			}
		}

	    OpenXcom::disconnectRendezvousUdp();

		// SPEC 16 (W1-P17) M4 (bugfix, WV-D77 traced via coop-DEBUG-M4
		// instrumentation, 2026-09-17): a client's battle_leave can already
		// be sitting in g_rxQ the instant this HOST-side reactive teardown
		// runs - onConnect==-2 detection (above, in updateCoopTask()) and
		// the client's own send race on the SAME tick, and THIS branch runs
		// BEFORE updateCoopTask()'s normal "drain g_rxQ into g_rxHold, then
		// dispatch" pump step - so clearNetworkSessionQueues()'s own g_rxQ
		// drain-and-discard a few lines below would silently destroy the
		// message before onTCPMessage() (connectionTCP.cpp's battle_leave
		// case) ever saw it, leaving peerLeftByChoice permanently false for
		// a battle_leave that DID arrive in time. Peek g_rxQ here, BEFORE it
		// is wiped, and apply any battle_leave found exactly like
		// onTCPMessage's own handler does. Scoped to spareAuthorityOnPeerAbsent:
		// peerLeftByChoice is only ever read by the M1 pause it is about to
		// enter, so there is nothing to preserve on a full teardown.
		if (spareAuthorityOnPeerAbsent)
		{
			std::string queuedMsg;
			while (g_rxQ.pop(queuedMsg))
			{
				Json::CharReaderBuilder rb;
				std::unique_ptr<Json::CharReader> reader(rb.newCharReader());
				Json::Value queuedObj;
				std::string errs;
				const char* begin = queuedMsg.data();
				const char* end = begin + queuedMsg.size();
				if (reader->parse(begin, end, &queuedObj, &errs)
					&& queuedObj.get("state", "").asString() == "battle_leave")
				{
					coopBattleAuthority().peerLeftByChoice = true;
				}
				// every other queued message is stale for the paused battle
				// - it resumes only via a fresh rejoin-restream (M5) - so
				// dropping it here is the SAME "stale queues must still
				// drop" call clearNetworkSessionQueues() makes a few lines
				// below; this loop is that same drain, done one step
				// earlier, only so battle_leave can be read on the way past.
			}
		}

		// Clear all shared TCP/UDP packet queues after the transport is stopped.
		// This prevents stale packets from the previous session from affecting
		// a newly hosted or joined session. SPEC 16 M1: on the mid-Active-battle
		// leave path this spares resetBattleAuthority()/CoopIdMaps::reset()/
		// CoopHandshake::resetPendingState() so the battle, battleId, seat map,
		// turnMode and baton survive; the queue clear itself (CoopPump::reset,
		// g_txQ/g_rxQ) still runs unconditionally either way - a rejoin
		// re-streams, so stale queues must still drop.
		OpenXcom::clearNetworkSessionQueues(!spareAuthorityOnPeerAbsent);
		if (spareAuthorityOnPeerAbsent)
		{
			coopBattleAuthority().peerAbsent = true;
		}

		deleteAllCoopBases();

		// issue #93: when the host vanishes the client is TOLD, and leaves when it
		// says so. CoopState(21) "Server connection lost" is pushed just before
		// this teardown runs (its ctor calls us), and its OK button owns the trip
		// to the main menu now - so jumping there ourselves would wipe the message
		// the player never got to read, mid-battle worst of all.
		bool lostDialogPresent = false;
		for (State* st : _game->getStates())
		{
			CoopState* cs = dynamic_cast<CoopState*>(st);
			if (cs && cs->getStateCode() == 21)
			{
				lostDialogPresent = true;
				break;
			}
		}

		// both
		// issue #79: not after the campaign has ended. The player is on the
		// defeat/victory statistics screen with their own OK button; yanking
		// them to the main menu because the other side closed the game first
		// is exactly the "one player's exit affects the other" bug.
		// A no_bases host (PvP alien side) must NOT be sent to the main menu
		// here — the freeze dialog handles the reconnection flow, and ripping
		// the world out from under it breaks rejoin entirely.
		if (!teardownAsHost && !isMain
			&& connectionTCP::_coopCampaign == true && !campaignEnded()
			&& !lostDialogPresent)
		{
			// issue #82: via GoToMainMenuState so the battle this client was in is
			// dropped with the rest of the world - a battle left on the SavedGame hands
			// the battlescape palette to every menu opened afterwards.
			_game->setState(new GoToMainMenuState(false));
		}

		// host
		if (teardownAsHost && onConnect == -2)
		{

			onConnect = 1;

			// issue #93: route on "is a mission running", not on the lobby mode.
			// A skirmish (NEW BATTLE > COOP) battle used to raise the LOBBY over
			// the tactical map on a drop - a menu whose RESUME GAME then threw the
			// battle away - while the campaign path already did the right thing.
			// A drop with no battle running (host still on the NEW BATTLE setup
			// screen) keeps re-opening the lobby: that IS where it belongs.
			if ((connectionTCP::session.lobbyMode != 0 || coopBattleLive(_game))
				&& connectionTCP::session.lobbyClosed == true)
			{
				// mid-session client drop: wait until they reconnect (D5). The
				// dialog sits over the geoscape/battlescape, pausing it. Never
				// stack a second one when a player-wait is already present
				// ANYWHERE in the stack, not just on top - two of them means two
				// RESUME buttons and a double campaign_begun broadcast (C9). The
				// one already there re-words itself for the drop, so it covers
				// this case (CoopState::waitingTitle).
				bool waitDialogPresent = false;
				for (State* st : _game->getStates())
				{
					CoopState* cs = dynamic_cast<CoopState*>(st);
					if (cs && cs->getStateCode() == COOP_DLG_WAIT_PLAYERS)
					{
						waitDialogPresent = true;
						break;
					}
				}
				// issue #79: and never once the campaign is over. After a
				// defeat/victory there is nothing left to do together, so a
				// client walking away is not a drop to freeze and wait on -
				// the host must be free to finish its own end-of-game screens.
				if (campaignEnded())
				{
					Log(LOG_INFO) << "[coop] freeze dialog suppressed: the campaign "
						"has ended; the peer has nothing left to reconnect for";
				}
				else if (spareAuthorityOnPeerAbsent)
				{
					// SPEC 16 M2 (drain-first): the co-op battle authority
					// survives this leave (M1), so the host's in-flight
					// BState chain (a walk, a turn, an AI/endturn side) must
					// be allowed to drain to its own boundary (action_end /
					// side_begin) before the pause modal steals the top of
					// the state stack - pushing it here, synchronously, would
					// freeze the battlescape's think() mid-chain, since only
					// the TOP state thinks. Defer to the RB-D5 pump point's
					// quiescence check (connectionTCP::updateCoopTask())
					// instead; it consumes g_coopPauseModalPending the moment
					// CoopArbiter::currentActionId() reads 0.
					if (!waitDialogPresent)
					{
						g_coopPauseModalPending = true;
					}
				}
				else if (!waitDialogPresent)
				{
					connectionTCP::session.freeze();
					_game->pushState(new CoopState(COOP_DLG_WAIT_PLAYERS));
				}
				else
				{
					Log(LOG_INFO) << "[coop] freeze dialog suppressed: a campaign "
						"wait dialog (freeze/resume-ack) is already on the stack";
				}
			}
			else if (connectionTCP::session.lobbyClosed == true
				&& !customBattleDebriefing)
			{
				_game->pushState(new LobbyMenu);
			}
			else if (customBattleDebriefing)
			{
				Log(LOG_INFO) << "[coop] lobby suppressed: client disconnected "
					"while the host was viewing custom-battle debriefing";
			}

		}
		// client
		else
		{

			onConnect = -1;

			// The client's world came from the host and is re-streamed on the
			// next join; drop the session's blobs.
			{
				std::lock_guard<std::mutex> lock(coopFilesMutex);
				connectionTCP::coopFilesClient.clear();
			}

			if (_chatMenu)
			{

				_chatMenu->setActive(false);
				_chatMenu->clearMessages();

				delete getChatMenu();
				setChatMenu(nullptr);
			}

		}

		// Session-state resets: exactly two paths (see CoopSession). The host
		// keeps its campaign/lobby context across a peer drop (D5); a client's
		// session is over. Never clear individual fields here.
		if (teardownAsHost)
		{
			connectionTCP::session.onClientDrop();
			// W1-P13b (WR-20): a client leaving mid-battle changes the live
			// -seat set - recompute `needed`, discard the departed seat's
			// own stored ready, and re-emit the tally so the surviving
			// seat(s) can still close the side. Self-guarded (isCoopBattle()
			// && hostSim inside); a no-op here whenever the battle already
			// ended or never started (getStaticBattle() null).
			//
			// D98/D91: NOT on the M1 mid-Active pause path
			// (spareAuthorityOnPeerAbsent). The absent seat there is
			// PAUSED-and-coming-back, not gone - recomputing `needed` down
			// to the surviving seat count would leave the host armed to
			// close the side SOLO (a "END TURN 1/1" state), which D91
			// forbids. The tally must freeze at its pre-drop value; a
			// rejoin re-streams the live seat set and any subsequent real
			// teardown still calls onSeatSetChanged() below, unguarded.
			if (!spareAuthorityOnPeerAbsent)
			{
				CoopEndTurn::onSeatSetChanged(connectionTCP::getStaticBattle());
			}
		}
		else
		{
			connectionTCP::session.resetSession();
		}

		connectionTCP::no_bases = false;
		connectionTCP::isCoopBaseLoading = false;

		gamePaused = 0;
		playerInsideCoopBase = false;

		_coop_task_completed = true;

		_isActiveAISync = false;

		_isActivePlayerSync = false;

		_clientPanicHandle = false;

		sendFileClient = false;
		sendFileBase = false;
		sendFileHost = false;
		sendFileSave = false;
		onceTime = false;

		isWaitMap = true;
		_hasHitUnit = -1;

		_game->getCoopMod()->pve2_init = false;

		setPlayerTurn(2);

		_battleWindow = false;
		_battleInit = false;

		coopInventory = false;

		// R1-P4: the BattlescapeState::setCurrentTurn(2) mirror write that used
		// to run here is gone - a coop hook the r1 vanilla restore stripped.
		// setPlayerTurn(2) above (connectionTCP's own tracked state) is the
		// surviving source of truth; the mirror returns with r2 (RB-D9/RB-D11).
}

