// W2-P7 S-C-A.2 (AMENDMENT P7-6 section 4.1 step 7, PR-5; F2527, F2530): LoadGameState :250-279's world half for the
// world held under @a key - sends nothing, pushes no state. False (the live world kept) when it is missing or fails.
bool connectionTCP::coopAdoptWorldInPlace(const std::string& key)
{
	{
		std::lock_guard<std::mutex> lock(coopFilesMutex);
		auto it = coopFilesClient.find(key);
		if (it == coopFilesClient.end() || it->second.empty())
		{
			Log(LOG_ERROR) << "[coop-debrief] client: no held world blob '" << key << "' - nothing adopted";
			return false;
		}
	}
	SavedGame* s = new SavedGame();
	try
	{
		s->loadCoopSaveFromMemory(key, _game->getMod(), _game->getLanguage(), key);
	}
	catch (const std::exception& e)
	{
		delete s;
		Log(LOG_ERROR) << "[coop-debrief] client: the held world did not load - nothing adopted: " << e.what();
		return false;
	}
	_game->setSavedGame(s);
	coop_save_owner_player_id = 1;
	SharedEcon::notifyWorldAdopted();
	return true;
}

// W2-P7 S-C-D1.2 (AMENDMENT P7-7 PR-23; D176, PR-9): CLIENT - right after EVERY in-place adoption, the display-only
// debriefing's page 3 goes live on the adopted world: _base re-pointed into the newest world (null when the payload's
// baseIndex is absent or out of range), _destroyBase and the Sell/Transfer visibility from the payload, then vanilla's
// own applyVisibility(). Vanilla parity: on a destroyed base the buttons show and do nothing (btnSellClick /
// btnTransferClick guard !_destroyBase). No DebriefingState edit (friend access).
void connectionTCP::coopDebriefPage3Live(DebriefingState* deb)
{
	if (!deb)
		return;
	const Json::Value msg = CoopDelta::debriefResultCopy();
	const Json::Value& d = msg["debrief"];
	SavedGame* sg = _game->getSavedGame();
	const int idx = d.get("baseIndex", -1).asInt();
	deb->_destroyBase = d.get("destroyBase", false).asBool();
	deb->_base = (sg && idx >= 0 && idx < (int)sg->getBases()->size()) ? sg->getBases()->at(idx) : nullptr;
	deb->_showSellButton = d.get("showSell", false).asBool() && (deb->_base != nullptr || deb->_destroyBase);
	deb->applyVisibility();
	Json::Value page3 = CoopDelta::battleEndRecord()["page3"];
	page3["live"] = 1;
	page3["baseIndex"] = deb->_base ? idx : -1;
	CoopDelta::battleEndRecordSet("page3", page3);
	Log(LOG_INFO) << "[coop-debrief] client: page 3 live on the adopted world - baseIndex=" << (deb->_base ? idx : -1)
		<< " showSell=" << deb->_showSellButton << " destroyBase=" << deb->_destroyBase;
}

// W2-P7 S-C-D2.2 (AMENDMENT P7-7 PR-29; D154, D175): CLIENT, SHARED - the campaign OK's LAST step: vanilla's forced
// screens (DebriefingState :913, :933-975) on the adopted world, with the payload's limitsEnforced / containment as
// _limitsEnforced / _containmentStateInfo and vanilla's refresh rule on the LIVE world, so whatever the host already
// solved never shows. Vanilla's strings, colours, background and the debriefing's palette (setState only queued it).
void connectionTCP::coopSharedForcedScreens(Game* game, DebriefingState* db)
{
	if (!game || !db || db->_destroyBase || !db->_base)
		return;
	const Json::Value msg = CoopDelta::debriefResultCopy();
	const Json::Value& d = msg["debrief"];
	Base* base = db->_base;
	const int limitsEnforced = d.get("limitsEnforced", 0).asInt();
	std::map<int, int> info;
	for (const auto& c : d["containment"])
		info[c.get("prisonType", 0).asInt()] = c.get("state", 0).asInt();
	for (auto& pair : info)
	{
		if (pair.second == 2)
		{
			const int availableContainment = base->getAvailableContainment(pair.first);
			const int usedContainment = base->getUsedContainment(pair.first);
			const int freeContainment = availableContainment - (usedContainment * limitsEnforced);
			if ((availableContainment > 0 && freeContainment >= 0) || usedContainment == 0)
				pair.second = 0; // 0 = OK (solved before this OK)
		}
	}
	Language* lang = game->getLanguage();
	RuleInterface* ui = game->getMod()->getInterface("debriefing");
	const Uint8 color = ui->getElement("errorMessage")->color;
	const int bgColor = ui->getElement("errorPalette")->color;
	auto trAlt = [lang](const std::string& id, int alt) { return lang->getString(alt > 0 ? id + "_" + std::to_string(alt) : id); };
	Json::Value contRec(Json::arrayValue);
	for (const auto& pair : info)
	{
		Json::Value e(Json::objectValue);
		e["prisonType"] = pair.first;
		e["state"] = pair.second;
		e["pushed"] = (pair.second == 1 || pair.second == 2) ? 1 : 0;
		if (pair.second == 2)
		{
			game->pushState(new ManageAlienContainmentState(base, pair.first, OPT_BATTLESCAPE));
			game->pushState(new ErrorMessageState(trAlt("STR_CONTAINMENT_EXCEEDED", pair.first).arg(base->getName()),
				db->_palette, color, "BACK01.SCR", bgColor));
		}
		else if (pair.second == 1)
		{
			game->pushState(new ErrorMessageState(trAlt("STR_ALIEN_DIES_NO_ALIEN_CONTAINMENT_FACILITY", pair.first),
				db->_palette, color, "BACK01.SCR", bgColor));
		}
		contRec.append(e);
	}
	const bool storage = limitsEnforced && base->storesOverfull();
	if (storage)
	{
		game->pushState(new SellState(base, 0, OPT_BATTLESCAPE));
		game->pushState(new ErrorMessageState(lang->getString("STR_STORAGE_EXCEEDED").arg(base->getName()), db->_palette,
			color, "BACK01.SCR", bgColor));
	}
	Json::Value forced(Json::objectValue);
	forced["containment"] = contRec;
	forced["storage"] = storage ? 1 : 0;
	CoopDelta::battleEndRecordSet("forced", forced);
	Log(LOG_INFO) << "[coop-debrief] client: forced screens after the OK - containment entries=" << contRec.size()
		<< " storage=" << (storage ? 1 : 0);
}

// W2-P7 S-C-D1.2 (AMENDMENT P7-7 PR-25; MR14, F2506, F5571): the page-3 bookkeeping of a SHARED sell / transfer
// that carries `debrief` (a page-3 screen's confirm), run by the `sell` / `transfer` appliers on the host AND every
// replica. (i) Every `autosell` entry is applied on EVERY machine (saved world state: the CmdApplier determinism
// rule). (ii) This machine's open campaign debriefing (the client's display-only one or the host's battle-end one),
// if any, loses each payload item's quantity (vanilla's SellState / TransferItemsState page-3 decrement) and hides
// its Sell/Transfer buttons once nothing recovered is left. A machine with no open debriefing books (i) only.
void connectionTCP::coopDebriefRecoveredSold(Game* game, const Json::Value& payload, bool sell)
{
	if (!game || !game->getMod())
		return;
	Mod* mod = game->getMod();
	SavedGame* save = game->getSavedGame();
	const Json::Value& autosell = payload["autosell"];
	int autosellN = 0;
	if (save && autosell.isObject())
	{
		for (const auto& type : autosell.getMemberNames())
		{
			RuleItem* rule = mod->getItem(type, false);
			if (!rule)
				continue;
			save->setAutosell(rule, autosell[type].asBool());
			++autosellN;
		}
	}
	DebriefingState* open = nullptr;
	if (CoopDelta::debriefIsCampaign())
	{
		for (State* st : game->getStates())
		{
			DebriefingState* db = dynamic_cast<DebriefingState*>(st);
			if (db && (CoopDelta::debriefIsDisplayOnly(db) || CoopDelta::debriefIsHostBattleEnd(db)))
			{
				open = db;
				break;
			}
		}
	}
	if (!open)
	{
		Log(LOG_INFO) << "[coop-debrief] page-3 " << (sell ? "sell" : "transfer") << " applied - autosell marks="
			<< autosellN << ", no open debriefing on this machine";
		return;
	}
	const Json::Value& items = payload["items"];
	if (items.isArray())
	{
		for (const auto& it : items)
		{
			const int qty = it.get("qty", 0).asInt();
			RuleItem* rule = mod->getItem(it.get("rule", "").asString(), false);
			if (rule && qty > 0)
				open->decreaseRecoveredItemCount(rule, qty);
		}
	}
	const int left = open->getTotalRecoveredItemCount();
	if (left <= 0)
		open->hideSellTransferButtons();
	Json::Value page3 = CoopDelta::battleEndRecord()["page3"];
	page3["sold"] = page3.get("sold", 0).asInt() + 1;
	CoopDelta::battleEndRecordSet("page3", page3);
	Log(LOG_INFO) << "[coop-debrief] page-3 " << (sell ? "sell" : "transfer") << " booked on this machine's debriefing"
		" - autosell marks=" << autosellN << " recovered left=" << left << (left <= 0 ? " (Sell/Transfer hidden)" : "");
}

